const DAY_MS = 24 * 60 * 60 * 1000

function ServiceStateBadge({ open }) {
  return <Badge tone={open ? "success" : "neutral"}>{open ? "Open" : "Closed"}</Badge>
}



function DatePicker({ id, value, onChange, placeholder = "mm/dd/yyyy" }) {
  const [open, setOpen] = useState(false)
  const [currentMonth, setCurrentMonth] = useState(new Date())
  const ref = useRef(null)

  useEffect(() => {
    if (value) {
      const d = new Date(value + "T12:00:00")
      if (!isNaN(d)) setCurrentMonth(d)
    }
  }, [value])

  useEffect(() => {
    function handleClickOutside(e) {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false)
    }
    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [])

  const year = currentMonth.getFullYear()
  const month = currentMonth.getMonth()

  const daysInMonth = new Date(year, month + 1, 0).getDate()
  const firstDay = new Date(year, month, 1).getDay()

  const days = []
  for (let i = 0; i < firstDay; i++) days.push(null)
  for (let i = 1; i <= daysInMonth; i++) days.push(new Date(year, month, i))

  function handleSelect(d) {
    const y = d.getFullYear()
    const m = String(d.getMonth() + 1).padStart(2, "0")
    const day = String(d.getDate()).padStart(2, "0")
    onChange({ target: { value: `${y}-${m}-${day}` } })
    setOpen(false)
  }

  const selectedDate = value ? new Date(value + "T12:00:00") : null
  const displayValue =
    selectedDate && !isNaN(selectedDate)
      ? selectedDate.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })
      : ""

  return (
    <div className="relative" ref={ref}>
      <button
        id={id}
        type="button"
        onClick={() => setOpen(!open)}
        className={`flex w-full items-center justify-between rounded-xl border border-border bg-card py-2 pl-3 pr-3 text-sm transition-all hover:border-primary/40 focus:outline-none focus:ring-2 focus:ring-ring ${
          displayValue ? "text-foreground" : "text-muted-foreground"
        }`}
      >
        <span className="truncate">{displayValue || placeholder}</span>
        <CalendarIcon className="size-4 shrink-0 text-muted-foreground" />
      </button>

      {open && (
        <div className="absolute right-0 z-50 mt-1 w-64 rounded-xl border border-border bg-card p-3 shadow-xl animate-in fade-in zoom-in-95 sm:left-0 sm:right-auto">
          <div className="mb-2 flex items-center justify-between">
            <button
              type="button"
              onClick={() => setCurrentMonth(new Date(year, month - 1, 1))}
              className="rounded-md p-1 text-muted-foreground hover:bg-muted hover:text-foreground"
            >
              <ChevronLeft className="size-4" />
            </button>
            <div className="text-sm font-semibold text-foreground">
              {currentMonth.toLocaleString("default", { month: "long" })} {year}
            </div>
            <button
              type="button"
              onClick={() => setCurrentMonth(new Date(year, month + 1, 1))}
              className="rounded-md p-1 text-muted-foreground hover:bg-muted hover:text-foreground"
            >
              <ChevronRight className="size-4" />
            </button>
          </div>
          <div className="mb-1 grid grid-cols-7 gap-1 text-center">
            {["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((d) => (
              <div key={d} className="text-[10px] font-medium uppercase text-muted-foreground">
                {d}
              </div>
            ))}
          </div>
          <div className="grid grid-cols-7 gap-1">
            {days.map((d, i) => {
              if (!d) return <div key={`empty-${i}`} />
              const isSelected = selectedDate && d.toDateString() === selectedDate.toDateString()
              const isToday = d.toDateString() === new Date().toDateString()

              return (
                <button
                  key={i}
                  type="button"
                  onClick={() => handleSelect(d)}
                  className={`flex size-7 items-center justify-center rounded-lg text-xs transition-colors hover:bg-muted hover:text-foreground ${
                    isSelected
                      ? "bg-primary font-semibold text-primary-foreground hover:bg-primary hover:text-primary-foreground"
                      : isToday
                        ? "bg-muted font-semibold text-foreground"
                        : "text-foreground"
                  }`}
                >
                  {d.getDate()}
                </button>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

function DateRangePicker({ id, startDate, endDate, onChange }) {
  const [open, setOpen] = useState(false)
  const [currentMonth, setCurrentMonth] = useState(new Date())
  const ref = useRef(null)

  useEffect(() => {
    if (startDate) {
      const d = new Date(startDate + "T12:00:00")
      if (!isNaN(d)) setCurrentMonth(d)
    }
  }, [startDate])

  useEffect(() => {
    function handleClickOutside(e) {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false)
    }
    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [])

  const year = currentMonth.getFullYear()
  const month = currentMonth.getMonth()

  const daysInMonth = new Date(year, month + 1, 0).getDate()
  const firstDay = new Date(year, month, 1).getDay()

  const days = []
  for (let i = 0; i < firstDay; i++) days.push(null)
  for (let i = 1; i <= daysInMonth; i++) days.push(new Date(year, month, i))

  function handleSelect(d) {
    const y = d.getFullYear()
    const m = String(d.getMonth() + 1).padStart(2, "0")
    const day = String(d.getDate()).padStart(2, "0")
    const dateStr = `${y}-${m}-${day}`
    
    if (!startDate || (startDate && endDate)) {
      onChange({ start: dateStr, end: "" })
    } else {
      const dStart = new Date(startDate + "T12:00:00")
      dStart.setHours(0, 0, 0, 0)
      if (d < dStart) {
        onChange({ start: dateStr, end: "" })
      } else {
        onChange({ start: startDate, end: dateStr })
        setOpen(false)
      }
    }
  }

  const sDate = startDate ? new Date(startDate + "T12:00:00") : null
  const eDate = endDate ? new Date(endDate + "T12:00:00") : null

  const displayValue = sDate && eDate 
    ? `${sDate.toLocaleDateString(undefined, { month: "short", day: "numeric" })} - ${eDate.toLocaleDateString(undefined, { month: "short", day: "numeric" })}`
    : sDate
      ? `${sDate.toLocaleDateString(undefined, { month: "short", day: "numeric" })} - Select end...`
      : ""

  return (
    <div className="relative w-full" ref={ref}>
      <button
        id={id}
        type="button"
        onClick={() => setOpen(!open)}
        className={`flex w-full items-center justify-between rounded-xl border border-border bg-card py-2 pl-3 pr-3 text-sm transition-all hover:border-primary/40 focus:outline-none focus:ring-2 focus:ring-ring ${
          startDate ? "text-foreground" : "text-muted-foreground"
        }`}
      >
        <span className="truncate">{displayValue || "Any time"}</span>
        <CalendarIcon className="size-4 shrink-0 text-muted-foreground" />
      </button>

      {open && (
        <div className="absolute left-0 z-50 mt-1 w-full rounded-xl border border-border bg-card p-3 shadow-xl animate-in fade-in zoom-in-95">
          <div className="mb-2 flex items-center justify-between">
            <button
              type="button"
              onClick={() => setCurrentMonth(new Date(year, month - 1, 1))}
              className="rounded-md p-1 text-muted-foreground hover:bg-muted hover:text-foreground"
            >
              <ChevronLeft className="size-4" />
            </button>
            <div className="text-sm font-semibold text-foreground">
              {currentMonth.toLocaleString("default", { month: "long" })} {year}
            </div>
            <button
              type="button"
              onClick={() => setCurrentMonth(new Date(year, month + 1, 1))}
              className="rounded-md p-1 text-muted-foreground hover:bg-muted hover:text-foreground"
            >
              <ChevronRight className="size-4" />
            </button>
          </div>
          <div className="mb-1 grid grid-cols-7 gap-1 text-center">
            {["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((d) => (
              <div key={d} className="text-[10px] font-medium uppercase text-muted-foreground">
                {d}
              </div>
            ))}
          </div>
          <div className="grid grid-cols-7 gap-1">
            {days.map((d, i) => {
              if (!d) return <div key={`empty-${i}`} />
              const isStart = sDate && d.toDateString() === sDate.toDateString()
              const isEnd = eDate && d.toDateString() === eDate.toDateString()
              const isBetween = sDate && eDate && d > sDate && d < eDate
              const isToday = d.toDateString() === new Date().toDateString()
              const isFuture = d > new Date()

              let bgClass = "text-foreground hover:bg-muted hover:text-foreground"
              if (isStart || isEnd) {
                bgClass = "bg-primary font-semibold text-primary-foreground hover:bg-primary hover:text-primary-foreground"
              } else if (isBetween) {
                bgClass = "bg-[#e6f4f1] text-[#0d7a74] font-medium hover:bg-[#d1eae5]"
              } else if (isToday) {
                bgClass = "bg-muted font-semibold text-foreground hover:bg-muted"
              }

              if (isFuture) {
                bgClass = "text-muted-foreground opacity-50 cursor-not-allowed"
              }

              return (
                <button
                  key={i}
                  type="button"
                  onClick={() => !isFuture && handleSelect(d)}
                  disabled={isFuture}
                  className={`flex h-8 w-full items-center justify-center rounded-lg text-xs transition-colors mx-auto ${bgClass}`}
                >
                  {d.getDate()}
                </button>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

const PRIORITY_RANK = { high: 1, medium: 2, low: 3 }

function useServiceFilterSort(services, orderedQueue) {
  const [sortBy, setSortBy] = useState("default")

  const processedServices = useMemo(() => {
    let result = [...services]
    
    if (sortBy === "students-high") {
      result.sort((a, b) => orderedQueue(b.id).length - orderedQueue(a.id).length)
    } else if (sortBy === "students-low") {
      result.sort((a, b) => orderedQueue(a.id).length - orderedQueue(b.id).length)
    } else if (sortBy === "priority-high") {
      result.sort((a, b) => PRIORITY_RANK[a.priority] - PRIORITY_RANK[b.priority])
    } else if (sortBy === "priority-low") {
      result.sort((a, b) => PRIORITY_RANK[b.priority] - PRIORITY_RANK[a.priority])
    }
    
    return result
  }, [services, orderedQueue, sortBy])

  const controls = (
    <div className="flex items-center gap-2">
      <div className="w-48">
        <Select value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
          <option value="default">Default Sort</option>
          <option value="students-high">Most Students</option>
          <option value="students-low">Fewest Students</option>
          <option value="priority-high">Priority (High - Low)</option>
          <option value="priority-low">Priority (Low - High)</option>
        </Select>
      </div>
    </div>
  )

  return { processedServices, controls }
}

function AdminDashboard({ onEditService, onManageQueue }) {
  const { services, orderedQueue, estimatedWait, toggleServiceOpen } = useApp()
  const { processedServices, controls } = useServiceFilterSort(services, orderedQueue)

  const totalWaiting = services.reduce((sum, s) => sum + orderedQueue(s.id).length, 0)
  const openServices = services.filter((s) => s.open)
  const highPriorityOpen = openServices.filter((s) => s.priority === "high").length

  return (
    <div className="mx-auto max-w-6xl space-y-6">
      <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
        {[
          { icon: Users, label: "Students waiting", value: String(totalWaiting) },
          { icon: CheckCircle2, label: "Open services", value: String(openServices.length) },
          { icon: Clock, label: "Total services", value: String(services.length) },
          { icon: TriangleAlert, label: "High priority open", value: String(highPriorityOpen) },
        ].map(({ icon: Icon, label, value }, i) => (
          <Card key={label} className={`animate-card delay-${i + 1}`}>
            <CardContent className="space-y-2 p-5">
              <span className="flex size-9 items-center justify-center rounded-lg bg-muted text-muted-foreground">
                <Icon className="size-[18px]" />
              </span>
              <p className="text-2xl font-semibold tracking-tight">{value}</p>
              <p className="text-xs text-muted-foreground">{label}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      <div>
        <div className="mb-4 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex items-center gap-4">
            <h2 className="font-semibold">Services</h2>
            {controls}
          </div>
          <button
            type="button"
            onClick={() => onEditService(null)}
            className="flex shrink-0 items-center gap-1.5 text-sm font-medium text-primary hover:underline"
          >
            <Plus className="size-4" /> New service
          </button>
        </div>

        <div className="space-y-3">
          {processedServices.map((s, i) => {
            const count = orderedQueue(s.id).length
            const wait = estimatedWait(s.id, count + 1)
            return (
              <Card 
                key={s.id} 
                className="animate-fade-in-up cursor-pointer hover:shadow-md transition-shadow" 
                style={{ animationDelay: `${i * 60}ms` }}
                onClick={() => onManageQueue(s.id)}
              >
                <CardContent className="flex flex-col gap-4 p-4 sm:flex-row sm:items-center sm:justify-between">
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <p className="truncate font-medium">{s.name}</p>
                      <PriorityBadge priority={s.priority} />
                      <ServiceStateBadge open={s.open} />
                    </div>
                    <p className="mt-1 truncate text-sm text-muted-foreground">{s.description}</p>
                    <p className="mt-1 text-xs text-muted-foreground">
                      {s.open ? `${count} waiting · ${formatWait(wait)} for a new arrival` : "Not accepting new students"}
                    </p>
                  </div>
                  <div className="flex shrink-0 items-center gap-2">
                    <Button 
                      variant="outline" 
                      size="sm" 
                      className="h-9 rounded-md" 
                      onClick={(e) => {
                        e.stopPropagation()
                        onManageQueue(s.id)
                      }}
                    >
                      Manage queue
                    </Button>
                    <Button 
                      variant="outline" 
                      size="sm" 
                      className="h-9 rounded-md" 
                      onClick={(e) => {
                        e.stopPropagation()
                        onEditService(s.id)
                      }}
                    >
                      <Pencil className="size-3.5" /> Edit
                    </Button>
                    <Button
                      variant={s.open ? "destructive" : "default"}
                      size="sm"
                      className="h-9 rounded-md"
                      onClick={(e) => {
                        e.stopPropagation()
                        toggleServiceOpen(s.id)
                      }}
                    >
                      {s.open ? "Close" : "Open"}
                    </Button>
                  </div>
                </CardContent>
              </Card>
            )
          })}
        </div>
      </div>
    </div>
  )
}

const PRIORITIES = ["low", "medium", "high"]
const NAME_LIMIT = 100

function blankForm() {
  return { name: "", description: "", duration: "15", priority: "medium" }
}

function ServiceForm({ editing, onSaved, onCancelEdit }) {
  const { saveService, pushNotification } = useApp()
  const [form, setForm] = useState(editing ? { ...editing, duration: String(editing.duration) } : blankForm())
  const [errors, setErrors] = useState({})

  useEffect(() => {
    setForm(editing ? { ...editing, duration: String(editing.duration) } : blankForm())
    setErrors({})
  }, [editing])

  function set(key) {
    return (e) => setForm((f) => ({ ...f, [key]: e.target.value }))
  }

  function validate() {
    const e = {}
    if (!form.name.trim()) {
      e.name = "Service name is required."
    } else if (form.name.trim().length > NAME_LIMIT) {
      e.name = `Keep it under ${NAME_LIMIT} characters.`
    }
    if (!form.description.trim()) {
      e.description = "Description is required."
    }
    const duration = Number(form.duration)
    if (!form.duration || Number.isNaN(duration) || duration <= 0) {
      e.duration = "Enter the expected duration in minutes."
    }
    return e
  }

  function handleSubmit(ev) {
    ev.preventDefault()
    const e = validate()
    setErrors(e)
    if (Object.keys(e).length > 0) return

    saveService({
      id: editing?.id,
      name: form.name.trim(),
      description: form.description.trim(),
      duration: Number(form.duration),
      priority: form.priority,
      open: editing ? editing.open : true,
    })

    pushNotification({
      title: editing ? "Service updated" : "Service created",
      body: editing
        ? `${form.name.trim()} has been updated.`
        : `${form.name.trim()} is now available for students to join.`,
      tone: "success",
    })

    onSaved()
  }

  return (
    <Card>
      <CardContent className="space-y-4 p-5">
        <div className="flex items-center justify-between">
          <h2 className="font-semibold">{editing ? "Edit service" : "New service"}</h2>
          {editing && (
            <button
              type="button"
              onClick={onCancelEdit}
              className="text-xs font-medium text-muted-foreground hover:text-foreground"
            >
              Cancel edit
            </button>
          )}
        </div>

        <form onSubmit={handleSubmit} noValidate className="space-y-4">
          <div className="space-y-1">
            <label className="text-xs font-bold text-foreground" htmlFor="svc-name">
              Service name
            </label>
            <input
              id="svc-name"
              type="text"
              value={form.name}
              maxLength={NAME_LIMIT}
              onChange={set("name")}
              placeholder="e.g. Financial Aid Advising"
              className="w-full rounded-xl border border-border bg-card px-4 py-2.5 text-sm transition-all focus:border-transparent focus:outline-none focus:ring-2 focus:ring-ring"
            />
            {errors.name && <p className="text-[11px] font-medium text-destructive">{errors.name}</p>}
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-foreground" htmlFor="svc-description">
              Description
            </label>
            <textarea
              id="svc-description"
              rows={2}
              value={form.description}
              onChange={set("description")}
              placeholder="What should students expect from this visit?"
              className="w-full resize-none rounded-xl border border-border bg-card px-4 py-2.5 text-sm transition-all focus:border-transparent focus:outline-none focus:ring-2 focus:ring-ring"
            />
            {errors.description && <p className="text-[11px] font-medium text-destructive">{errors.description}</p>}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-bold text-foreground" htmlFor="svc-duration">
                Expected duration (min)
              </label>
              <input
                id="svc-duration"
                type="number"
                min={1}
                max={240}
                value={form.duration}
                onChange={set("duration")}
                className="w-full rounded-xl border border-border bg-card px-4 py-2.5 text-sm transition-all focus:border-transparent focus:outline-none focus:ring-2 focus:ring-ring"
              />
              {errors.duration && <p className="text-[11px] font-medium text-destructive">{errors.duration}</p>}
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold text-foreground" htmlFor="svc-priority">
                Priority level
              </label>
              <Select id="svc-priority" value={form.priority} onChange={set("priority")} className="pl-4 capitalize">
                {PRIORITIES.map((p) => (
                  <option key={p} value={p} className="capitalize">
                    {p}
                  </option>
                ))}
              </Select>
            </div>
          </div>

          <Button type="submit" className="h-10 w-full">
            {editing ? "Save changes" : "Create service"}
          </Button>
        </form>
      </CardContent>
    </Card>
  )
}

function ServiceManagement({ editingId, onEdit, onSaved }) {
  const { services, deleteService, toggleServiceOpen } = useApp()
  const editing = services.find((s) => s.id === editingId) || null

  return (
    <div className="mx-auto grid max-w-6xl gap-6 lg:grid-cols-5">
      <div className="lg:col-span-2">
        <ServiceForm editing={editing} onSaved={onSaved} onCancelEdit={() => onEdit(null)} />
      </div>

      <div className="space-y-3 lg:col-span-3">
        <h2 className="font-semibold">Existing services</h2>
        {services.map((s) => (
          <Card
            key={s.id}
            className={`transition-colors ${editingId === s.id ? "border-primary ring-1 ring-primary/30" : ""}`}
          >
            <CardContent className="flex items-center justify-between gap-4 p-4">
              <div className="min-w-0">
                <div className="flex flex-wrap items-center gap-2">
                  <p className="truncate font-medium">{s.name}</p>
                  <PriorityBadge priority={s.priority} />
                  <ServiceStateBadge open={s.open} />
                </div>
                <p className="mt-1 truncate text-sm text-muted-foreground">{s.description}</p>
                <p className="mt-1 text-xs text-muted-foreground">~{s.duration} min per visit</p>
              </div>
              <div className="flex shrink-0 items-center gap-2">
                <Button variant="outline" size="sm" className="h-9 rounded-md" onClick={() => onEdit(s.id)}>
                  <Pencil className="size-3.5" /> Edit
                </Button>
                <Button
                  variant={s.open ? "destructive" : "default"}
                  size="sm"
                  className="h-9 rounded-md"
                  onClick={() => toggleServiceOpen(s.id)}
                >
                  {s.open ? "Close" : "Open"}
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-9 rounded-md text-destructive hover:bg-destructive/10 hover:text-destructive"
                  onClick={() => deleteService(s.id)}
                >
                  <Trash2 className="size-3.5" />
                </Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  )
}

function QueueOverviewCard({ service, line, onOpen }) {
  return (
    <Card className="flex flex-col overflow-hidden">
      <CardContent className="flex flex-1 flex-col gap-3 p-5">
        <div className="flex items-start justify-between gap-3">
          <div>
            <h3 className="font-semibold">{service.name}</h3>
            <p className="mt-0.5 text-sm">
              <span className={service.open ? "font-medium text-[oklch(0.5_0.12_170)]" : "font-medium text-muted-foreground"}>
                {service.open ? "Open" : "Closed"}
              </span>
              <span className="text-muted-foreground"> · {line.length} student{line.length === 1 ? "" : "s"} in line</span>
            </p>
          </div>
          <div className="flex items-center gap-2">
            <PriorityBadge priority={service.priority} />
            <span className="flex size-8 shrink-0 items-center justify-center rounded-full bg-muted text-sm font-semibold text-foreground">
              {line.length}
            </span>
          </div>
        </div>

        {line.length > 0 && (
          <ul className="max-h-56 space-y-3 overflow-y-auto pr-1">
            {line.map((entry, idx) => (
              <li key={entry.id} className="flex items-start gap-3">
                <span className="mt-0.5 flex size-6 shrink-0 items-center justify-center rounded-full bg-muted text-xs font-semibold text-foreground">
                  {idx + 1}
                </span>
                <div className="min-w-0">
                  <p className="truncate text-sm font-medium">
                    {entry.studentName}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    Joined {relativeTime(entry.joinedAt)} ·{" "}
                    {formatWait((entry.__wait ?? 0))}
                  </p>
                </div>
              </li>
            ))}
          </ul>
        )}
      </CardContent>
      <button
        type="button"
        onClick={onOpen}
        className="border-t border-border px-5 py-3 text-left text-sm font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
      >
        Open queue
      </button>
    </Card>
  )
}

function QueueManagement({ selectedId, onSelect, onServe, onRemove }) {
  const { services, orderedQueue, estimatedWait, moveEntry } = useApp()
  const { processedServices, controls } = useServiceFilterSort(services, orderedQueue)
  const service = services.find((s) => s.id === selectedId) || null
  const line = useMemo(() => (service ? orderedQueue(service.id) : []), [service, orderedQueue])

  if (!service) {
    if (services.length === 0) {
      return <p className="mx-auto max-w-5xl text-sm text-muted-foreground">Create a service to start managing its queue.</p>
    }
    return (
      <div className="mx-auto max-w-5xl space-y-4">
        <div className="flex items-center gap-4 mb-4">
          <h2 className="font-semibold">Queues</h2>
          {controls}
        </div>
        <div className="grid gap-5 sm:grid-cols-2">
          {processedServices.map((s) => {
            const l = orderedQueue(s.id).map((entry, idx) => ({ ...entry, __wait: estimatedWait(s.id, idx + 1) }))
            return <QueueOverviewCard key={s.id} service={s} line={l} onOpen={() => onSelect(s.id)} />
          })}
        </div>
      </div>
    )
  }

  return (
    <div className="mx-auto max-w-5xl space-y-4">
      <button
        type="button"
        onClick={() => onSelect(null)}
        className="flex items-center gap-1.5 text-sm font-medium text-muted-foreground hover:text-foreground"
      >
        <ArrowLeft className="size-4" /> All queues
      </button>

      <Card>
        <CardContent className="p-0">
          <div className="flex items-center justify-between gap-3 border-b border-border p-5">
            <div>
              <div className="flex items-center gap-2">
                <h2 className="font-semibold">{service.name}</h2>
                <ServiceStateBadge open={service.open} />
              </div>
              <div className="mt-1 flex items-center gap-2">
                <PriorityBadge priority={service.priority} />
                <span className="text-sm text-muted-foreground">
                  {line.length} student{line.length === 1 ? "" : "s"} in line
                </span>
              </div>
            </div>
            <Button
              className="h-9 shrink-0"
              disabled={line.length === 0}
              onClick={() => onServe(service, line[0])}
            >
              <PhoneCall className="size-4" /> Serve next
            </Button>
          </div>

          {line.length === 0 ? (
            <div className="flex flex-col items-center justify-center gap-3 py-14 text-center">
              <span className="flex size-14 items-center justify-center rounded-full bg-muted text-muted-foreground">
                <Search className="size-6" />
              </span>
              <div>
                <p className="font-medium">No one is waiting</p>
                <p className="text-sm text-muted-foreground">Students who join this service will show up here.</p>
              </div>
            </div>
          ) : (
            <ul className="divide-y divide-border">
              {line.map((entry, idx) => (
                <li key={entry.id} className="flex items-center gap-4 p-4">
                  <span className="flex size-8 shrink-0 items-center justify-center rounded-full bg-muted text-sm font-semibold text-foreground">
                    {idx + 1}
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <p className="truncate font-medium">{entry.studentName}</p>
                    </div>
                    <p className="mt-0.5 text-xs text-muted-foreground">
                      Joined {relativeTime(entry.joinedAt)} · {formatWait(estimatedWait(service.id, idx + 1))}
                    </p>
                  </div>
                  <div className="flex shrink-0 items-center gap-1">
                    <button
                      type="button"
                      disabled={idx === 0}
                      onClick={() => moveEntry(entry.id, "up")}
                      aria-label={`Move ${entry.studentName} up`}
                      className="flex size-8 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:opacity-30"
                    >
                      <ArrowUp className="size-4" />
                    </button>
                    <button
                      type="button"
                      disabled={idx === line.length - 1}
                      onClick={() => moveEntry(entry.id, "down")}
                      aria-label={`Move ${entry.studentName} down`}
                      className="flex size-8 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:opacity-30"
                    >
                      <ArrowDown className="size-4" />
                    </button>
                    <button
                      type="button"
                      onClick={() => onRemove(service, entry)}
                      aria-label={`Remove ${entry.studentName}`}
                      className="flex size-8 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-destructive/10 hover:text-destructive"
                    >
                      <X className="size-4" />
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

const OUTCOME_CONFIG = {
  served: { label: "Served", tone: "success", Icon: CheckCircle2 },
  left: { label: "Left queue", tone: "neutral", Icon: LogOut },
  removed: { label: "Removed by admin", tone: "danger", Icon: XCircle },
  canceled: { label: "Canceled", tone: "danger", Icon: XCircle },
}

const DATE_PRESETS = [
  { key: "today", label: "Today" },
  { key: "week", label: "This week" },
  { key: "all", label: "All time" },
]

function toDateInputValue(ts) {
  const d = new Date(ts)
  const pad = (n) => String(n).padStart(2, "0")
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

function AdminHistory({ log }) {
  const { services } = useApp()
  const [serviceFilter, setServiceFilter] = useState("all")
  const [outcomeFilter, setOutcomeFilter] = useState("all")
  const [preset, setPreset] = useState("all")
  const [dateFrom, setDateFrom] = useState("")
  const [dateTo, setDateTo] = useState("")

  function applyPreset(key) {
    setPreset(key)
    if (key === "today") {
      const today = toDateInputValue(Date.now())
      setDateFrom(today)
      setDateTo(today)
    } else if (key === "week") {
      setDateFrom(toDateInputValue(Date.now() - 6 * DAY_MS))
      setDateTo(toDateInputValue(Date.now()))
    } else {
      setDateFrom("")
      setDateTo("")
    }
  }

  const filtered = useMemo(() => {
    return log.filter((entry) => {
      if (serviceFilter !== "all" && entry.serviceId !== serviceFilter) return false
      if (outcomeFilter !== "all" && entry.outcome !== outcomeFilter) return false
      if (dateFrom && new Date(entry.resolvedAt).getTime() < new Date(dateFrom + "T00:00:00").setHours(0, 0, 0, 0)) return false
      if (dateTo && new Date(entry.resolvedAt).getTime() > new Date(dateTo + "T00:00:00").setHours(23, 59, 59, 999)) return false
      return true
    })
  }, [log, serviceFilter, outcomeFilter, dateFrom, dateTo])

  const served = filtered.filter((e) => e.outcome === "served")
  const [backendAvgWait, setBackendAvgWait] = useState(null)

  useEffect(() => {
    const params = new URLSearchParams({ status: "served" })
    if (serviceFilter !== "all") params.set("serviceId", serviceFilter)
    fetch(`/api/history/summary?${params}`)
      .then((res) => (res.ok ? res.json() : Promise.reject(res.status)))
      .then((data) => setBackendAvgWait(data.avgWaitMinutes))
      .catch((err) => console.error("Failed to load history summary from backend:", err))
  }, [serviceFilter])

  const avgWait = backendAvgWait !== null
    ? backendAvgWait
    : served.length
      ? Math.round(served.reduce((sum, e) => sum + e.waitMinutes, 0) / served.length)
      : 0

  return (
    <div className="mx-auto max-w-5xl space-y-6">
      <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
        {[
          { label: "Matching visits", value: String(filtered.length) },
          { label: "Served", value: String(served.length) },
          { label: "Left / removed", value: String(filtered.length - served.length) },
          { label: "Avg. wait (served)", value: `${avgWait} min` },
        ].map((s) => (
          <Card key={s.label}>
            <CardContent className="p-5">
              <p className="text-2xl font-semibold tracking-tight">{s.value}</p>
              <p className="text-xs text-muted-foreground">{s.label}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      <Card>
        <CardContent className="space-y-4 p-5">
          <div className="flex flex-wrap gap-2">
            {DATE_PRESETS.map((p) => (
              <button
                key={p.key}
                type="button"
                onClick={() => applyPreset(p.key)}
                className={`rounded-lg px-3 py-1.5 text-xs font-semibold transition-colors ${
                  preset === p.key ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground hover:text-foreground"
                }`}
              >
                {p.label}
              </button>
            ))}
          </div>

          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
            <div className="space-y-1">
              <label className="text-xs font-bold text-foreground" htmlFor="hist-service">
                Service
              </label>
              <Select id="hist-service" value={serviceFilter} onChange={(e) => setServiceFilter(e.target.value)}>
                <option value="all">All services</option>
                {services.map((s) => (
                  <option key={s.id} value={s.id}>
                    {s.name}
                  </option>
                ))}
              </Select>
            </div>

            <div className="space-y-1">
              <label className="text-xs font-bold text-foreground" htmlFor="hist-outcome">
                Outcome
              </label>
              <Select id="hist-outcome" value={outcomeFilter} onChange={(e) => setOutcomeFilter(e.target.value)}>
                <option value="all">All outcomes</option>
                <option value="served">Served</option>
                <option value="left">Left queue</option>
                <option value="removed">Removed by admin</option>
              </Select>
            </div>

            <div className="space-y-1">
              <label className="text-xs font-bold text-foreground" htmlFor="hist-date">
                Date Range
              </label>
              <DateRangePicker
                id="hist-date"
                startDate={dateFrom}
                endDate={dateTo}
                onChange={({ start, end }) => {
                  setPreset("custom")
                  setDateFrom(start)
                  setDateTo(end)
                }}
              />
            </div>
          </div>

          {(serviceFilter !== "all" || outcomeFilter !== "all" || dateFrom || dateTo) && (
            <button
              type="button"
              onClick={() => {
                setServiceFilter("all")
                setOutcomeFilter("all")
                applyPreset("all")
              }}
              className="text-xs font-medium text-primary hover:underline"
            >
              Reset filters
            </button>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardContent className="divide-y divide-border p-0">
          {filtered.length === 0 && (
            <div className="flex flex-col items-center justify-center gap-3 py-14 text-center">
              <span className="flex size-14 items-center justify-center rounded-full bg-muted text-muted-foreground">
                <Search className="size-6" />
              </span>
              <div>
                <p className="font-medium">No visits match these filters</p>
                <p className="text-sm text-muted-foreground">Try widening the date range or clearing a filter.</p>
              </div>
            </div>
          )}
          {filtered.map((entry) => {
            const config = OUTCOME_CONFIG[entry.outcome] || { label: "Unknown", tone: "neutral", Icon: XCircle }
            const { label, tone, Icon } = config
            return (
              <div key={entry.id} className="flex items-center gap-4 p-4">
                <span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-muted text-muted-foreground">
                  <Icon className="size-5" />
                </span>
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="truncate font-medium">{entry.studentName}</p>
                    <PriorityBadge priority={entry.priority} />
                  </div>
                  <p className="truncate text-sm text-muted-foreground">{entry.serviceName}</p>
                  <p className="text-xs text-muted-foreground">
                    {new Date(entry.resolvedAt).toLocaleString([], {
                      month: "short",
                      day: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </p>
                </div>
                <div className="flex flex-col items-end gap-1.5">
                  <Badge tone={tone}>{label}</Badge>
                  {entry.outcome === "served" && (
                    <span className="flex items-center gap-1 text-xs text-muted-foreground">
                      <Clock className="size-3" /> {entry.waitMinutes} min wait
                    </span>
                  )}
                </div>
              </div>
            )
          })}
        </CardContent>
      </Card>
    </div>
  )
}

const REPORT_TYPES = [
  {
    key: "users",
    label: "Users & Queue Participation",
    description: "One row per completed visit — who joined, which service, priority, and outcome.",
    supportsDateRange: true,
    supportsServiceFilter: false,
    supportsGroupByService: false,
  },
  {
    key: "services",
    label: "Service Details & Activity",
    description: "One row per service — currently waiting, totals served/left/canceled, and average wait.",
    supportsDateRange: true,
    supportsServiceFilter: true,
    supportsGroupByService: false,
  },
  {
    key: "stats",
    label: "Queue Usage Statistics",
    description: "Overall totals and average wait time, or broken out per service.",
    supportsDateRange: true,
    supportsServiceFilter: false,
    supportsGroupByService: true,
  },
]

function ReportCard({ config, services }) {
  const { downloadReport } = useApp()
  const [startDate, setStartDate] = useState("")
  const [endDate, setEndDate] = useState("")
  const [serviceId, setServiceId] = useState("")
  const [groupByService, setGroupByService] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)
  const [success, setSuccess] = useState(false)

  async function handleDownload() {
    setLoading(true)
    setError(null)
    setSuccess(false)
    try {
      await downloadReport(config.key, {
        startDate: startDate || undefined,
        endDate: endDate || undefined,
        serviceId: config.supportsServiceFilter && serviceId ? serviceId : undefined,
        groupByService: config.supportsGroupByService ? groupByService : undefined,
        format: "csv",
      })
      setSuccess(true)
    } catch (err) {
      setError(err.message || "Failed to generate report.")
    } finally {
      setLoading(false)
    }
  }

  return (
    <Card>
      <CardContent className="space-y-4 p-6">
        <div className="flex items-start gap-3">
          <span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-muted text-muted-foreground">
            <FileText className="size-5" />
          </span>
          <div className="min-w-0 flex-1">
            <h3 className="font-medium text-foreground">{config.label}</h3>
            <p className="text-sm text-muted-foreground">{config.description}</p>
          </div>
        </div>

        {config.supportsDateRange && (
          <div>
            <label className="mb-1 block text-xs font-medium text-muted-foreground">Date Range</label>
            <DateRangePicker 
              startDate={startDate} 
              endDate={endDate} 
              onChange={({ start, end }) => {
                setStartDate(start)
                setEndDate(end)
              }} 
            />
          </div>
        )}

        {config.supportsServiceFilter && (
          <div>
            <label className="mb-1 block text-xs font-medium text-muted-foreground">Service</label>
            <Select value={serviceId} onChange={(e) => setServiceId(e.target.value)}>
              <option value="">All services</option>
              {services.map((s) => (
                <option key={s.id} value={s.id}>{s.name}</option>
              ))}
            </Select>
          </div>
        )}

        {config.supportsGroupByService && (
          <label className="flex items-center gap-2 text-sm text-foreground">
            <input
              type="checkbox"
              checked={groupByService}
              onChange={(e) => setGroupByService(e.target.checked)}
              className="size-4 rounded border-border"
            />
            Break down by service
          </label>
        )}

        {error && <p className="text-sm text-red-500">{error}</p>}
        {success && !error && <p className="text-sm text-green-600">Report downloaded.</p>}

        <div className="mt-4">
          <Button onClick={handleDownload} disabled={loading} className="w-full justify-center">
            <Download className="size-4 mr-2" />
            {loading ? "Generating..." : "Download Report"}
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

function ReportsPanel() {
  const { services } = useApp()

  return (
    <div className="mx-auto max-w-4xl space-y-6">
      <div className="grid gap-4 md:grid-cols-1">
        {REPORT_TYPES.map((config) => (
          <ReportCard key={config.key} config={config} services={services} />
        ))}
      </div>
    </div>
  )
}

function UserManagement() {
  const { admins, addAdmin, removeAdmin } = useApp()
  const [newEmail, setNewEmail] = useState("")
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)
  const [success, setSuccess] = useState(null)

  const handleAddAdmin = async (e) => {
    e.preventDefault()
    setLoading(true)
    setError(null)
    setSuccess(null)
    try {
      if (!newEmail.trim()) {
        throw new Error("Please enter an email address.")
      }
      await addAdmin(newEmail.trim())
      setSuccess(`Successfully added ${newEmail} as an admin.`)
      setNewEmail("")
    } catch (err) {
      setError(err.message || "Failed to add admin.")
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardContent className="p-6">
          <h3 className="text-lg font-medium text-slate-800 mb-4">Add New Admin</h3>
          <form onSubmit={handleAddAdmin} className="space-y-4">
            <div className="flex gap-4">
              <input
                type="email"
                value={newEmail}
                onChange={(e) => setNewEmail(e.target.value)}
                placeholder="admin@example.com"
                className="flex-1 px-3 py-2 border rounded-md"
                required
              />
              <Button type="submit" disabled={loading}>
                {loading ? "Adding..." : "Add Admin"}
              </Button>
            </div>
            {error && <p className="text-red-500 text-sm">{error}</p>}
            {success && <p className="text-green-500 text-sm">{success}</p>}
            <div className="bg-blue-50 text-blue-800 p-4 rounded-md text-sm">
              <p className="font-medium mb-1">Note:</p>
              <p>If they already have an account (Google or email), they will keep their password. If this is a new account, the default password is <strong>QueueSmart2026!</strong></p>
            </div>
          </form>
        </CardContent>
      </Card>

      <Card>
        <CardContent className="p-6">
          <h3 className="text-lg font-medium text-slate-800 mb-4">Current Admins</h3>
          <div className="divide-y border rounded-md">
            {admins.map(email => (
              <div key={email} className="flex justify-between items-center p-4">
                <span className="font-medium text-slate-700">{email}</span>
                {email !== "admin@queuesmart.com" ? (
                  <Button variant="outline" tone="danger" onClick={() => removeAdmin(email)}>
                    Remove
                  </Button>
                ) : (
                  <Badge tone="info">Master Admin</Badge>
                )}
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

function Admin() {
  const navigate = useNavigate()
  const { user, services, queues, history, serveNext, removeEntry } = useApp()
  const [view, setView] = useState("dashboard")
  const [editingId, setEditingId] = useState(null)
  const [selectedQueueId, setSelectedQueueId] = useState(null)

  useEffect(() => {
    if (!user) {
      navigate("/")
    } else if (user.role !== "admin") {
      navigate("/dashboard")
    }
  }, [user, navigate])

  const resolvedLog = useMemo(
    () => history.map((e) => ({
      id: e.id,
      studentName: e.studentName,
      serviceId: e.serviceId,
      serviceName: e.serviceName,
      priority: e.priority,
      outcome: e.outcomeRaw,
      resolvedAt: e.resolvedAt,
      waitMinutes: e.waitMinutes,
    })),
    [history],
  )

  if (!user || user.role !== "admin") return null

  function recordResolution(service, entry, outcome) {
    if (!entry) return
  }


  function handleServe(service, entry) {
    recordResolution(service, entry, "served")
    serveNext(service.id)
  }

  function handleRemove(service, entry) {
    recordResolution(service, entry, "removed")
    removeEntry(entry.id)
  }

  const { title, subtitle } = view === "queues" && selectedQueueId
    ? { title: meta.queues.title, subtitle: "Reorder, remove, or serve the next student" }
    : meta[view]

  function handleNavigate(key) {
    setView(key)
    if (key !== "services") setEditingId(null)
  }

  function goEditService(id) {
    setEditingId(id)
    setView("services")
  }

  function goManageQueue(id) {
    setSelectedQueueId(id)
    setView("queues")
  }

  return (
    <AppShell nav={nav} active={view} onNavigate={handleNavigate} title={title} subtitle={subtitle}>
      {view === "dashboard" && <AdminDashboard onEditService={goEditService} onManageQueue={goManageQueue} />}
      {view === "services" && (
        <ServiceManagement editingId={editingId} onEdit={setEditingId} onSaved={() => setEditingId(null)} />
      )}
      {view === "queues" && (
        <QueueManagement
          selectedId={selectedQueueId}
          onSelect={setSelectedQueueId}
          onServe={handleServe}
          onRemove={handleRemove}
        />
      )}
      {view === "history" && <AdminHistory log={resolvedLog} />}
      {view === "reports" && <ReportsPanel />}
      {view === "users" && <UserManagement />}
    </AppShell>
  )
}

export default Admin